cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

// specs/hal-engine-config-hooks/spec.md: any rejection reaches onError as an Error, the raw value kept as its cause.
describe('asError', () => {
  it('passes an Error through and wraps any other rejection with a readable message and the raw value as cause', () => {
    const original = new Error('boom');
    const object = {code: 503, detail: 'upstream down'};
    const view = (e: Error) => ({isError: e instanceof Error, message: e.message, cause: e.cause});

    expect({
      same: asError(original) === original,
      string: view(asError('string boom')),
      object: view(asError(object)),
      undefined: view(asError(undefined)),
    }).toEqual({
      same: true,
      string: {isError: true, message: 'string boom', cause: 'string boom'},
      object: {isError: true, message: '{"code":503,"detail":"upstream down"}', cause: object},
      undefined: {isError: true, message: 'undefined', cause: undefined},
    });
  });
});
EOF
