cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

// onError is typed against Error, so a non-Error rejection is wrapped rather than dropped; the raw value stays reachable as `cause`.
export function asError(reason: unknown): Error {
  if (reason instanceof Error) return reason;
  return new Error(readableMessage(reason), {cause: reason});
}

function readableMessage(reason: unknown): string {
  if (typeof reason === 'string') return reason;
  try {
    return JSON.stringify(reason) ?? String(reason);
  } catch {
    return String(reason);
  }
}
EOF
